pub fn gcd_i(mut m: i32, mut n: i32) -> i32 {
    // Both m and n must be strictly positive
    assert!(m > 0 && n > 0, "gcd_i requires positive integers");

    // Repeatedly subtract the smaller number from the larger
    // until they become equal. At that point, that value is the GCD.
    while m != n {
        if m > n {
            m -= n;
        } else {
            n -= m;
        }
    }

    m
}

